#!/usr/bin/env bash
# ingress-nginx/ingress-nginx 4.15.1 - base variant: default
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/ingress-nginx-ingress-nginx-4-15-1.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# Installer is a cub plugin. Check it before this script does any work.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'The cub installer plugin is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kustomize >/dev/null 2>&1; then
  printf 'kustomize is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the default base variant into ./ingress-nginx-ingress-nginx-4-15-1-default"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/ingress-nginx-ingress-nginx:4.15.1@sha256:dc0f6c1a8158230957c1cae1b26073339b009b220c79cff0e3df31e9f21c73e4 --base default --work-dir ./ingress-nginx-ingress-nginx-4-15-1-default --non-interactive --namespace ingress-nginx

say "Read what was rendered; nothing has touched the cluster yet"
ls ./ingress-nginx-ingress-nginx-4-15-1-default/out/manifests

say "Ensure the ingress-nginx namespace exists"
kubectl create namespace ingress-nginx --dry-run=client -o yaml | kubectl apply -f -

if [ "${REQUIREMENTS_READY:-0}" != "1" ]; then
  cat >&2 <<'EOF_REQUIREMENTS'
This base variant needs resources you must create with your own values first:
  - Secret ingress-nginx/ingress-nginx-admission keys cert,key,ca
    kubectl -n ingress-nginx create secret generic ingress-nginx-admission --from-literal=cert=<value> --from-literal=key=<value> --from-literal=ca=<value>
Complete these prerequisites before applying the rendered objects.
Replace any <...> placeholders with values or files for your environment.
When the resources exist, re-run with:
  REQUIREMENTS_READY=1 bash try.sh
EOF_REQUIREMENTS
  exit 1
fi

if [ -d ./ingress-nginx-ingress-nginx-4-15-1-default/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./ingress-nginx-ingress-nginx-4-15-1-default/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./ingress-nginx-ingress-nginx-4-15-1-default/out/manifests

say "Done. The cluster received exactly the files in ./ingress-nginx-ingress-nginx-4-15-1-default/out."
